CREATE SCHEMA IF NOT EXISTS portfolio;

CREATE TABLE IF NOT EXISTS portfolio."Roles" (
  "RoleId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "RoleName" text NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS portfolio."Users" (
  "UserId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" text NOT NULL,
  "Email" text NOT NULL UNIQUE,
  "PasswordHash" text NOT NULL,
  "RoleId" integer NOT NULL REFERENCES portfolio."Roles" ("RoleId"),
  "CreatedAt" timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS portfolio."SkillCategories" (
  "CategoryId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "CategoryName" text NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS portfolio."Projects" (
  "ProjectId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Title" text NOT NULL,
  "Description" text NOT NULL,
  "ImageUrl" text,
  "GitHubUrl" text,
  "LiveUrl" text,
  "CreatedAt" timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS portfolio."Profiles" (
  "ProfileId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UserId" integer NOT NULL UNIQUE REFERENCES portfolio."Users" ("UserId"),
  "FullName" text NOT NULL,
  "Title" text NOT NULL,
  "Bio" text,
  "ImageUrl" text,
  "Location" text,
  "CvUrl" text
);

CREATE TABLE IF NOT EXISTS portfolio."Skills" (
  "SkillId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" text NOT NULL,
  "IconUrl" text,
  "CategoryId" integer NOT NULL REFERENCES portfolio."SkillCategories" ("CategoryId")
);

CREATE TABLE IF NOT EXISTS portfolio."ProjectSkills" (
  "ProjectId" integer NOT NULL REFERENCES portfolio."Projects" ("ProjectId"),
  "SkillId" integer NOT NULL REFERENCES portfolio."Skills" ("SkillId"),
  PRIMARY KEY ("ProjectId", "SkillId")
);

CREATE TABLE IF NOT EXISTS portfolio."Favorites" (
  "UserId" integer NOT NULL REFERENCES portfolio."Users" ("UserId"),
  "ProjectId" integer NOT NULL REFERENCES portfolio."Projects" ("ProjectId"),
  "CreatedAt" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("UserId", "ProjectId")
);

CREATE TABLE IF NOT EXISTS portfolio."Educations" (
  "EducationId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ProfileId" integer NOT NULL REFERENCES portfolio."Profiles" ("ProfileId"),
  "Institution" text NOT NULL,
  "Degree" text,
  "FieldOfStudy" text,
  "StartDate" date,
  "EndDate" date,
  "Description" text
);

CREATE TABLE IF NOT EXISTS portfolio."Experiences" (
  "ExperienceId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ProfileId" integer NOT NULL REFERENCES portfolio."Profiles" ("ProfileId"),
  "CompanyName" text NOT NULL,
  "Position" text NOT NULL,
  "StartDate" date NOT NULL,
  "EndDate" date,
  "Description" text
);

CREATE TABLE IF NOT EXISTS portfolio."Messages" (
  "MessageId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" text NOT NULL,
  "Email" text NOT NULL,
  "Subject" text NOT NULL,
  "Content" text NOT NULL,
  "IsRead" boolean NOT NULL DEFAULT false,
  "CreatedAt" timestamptz NOT NULL DEFAULT now()
);
